const rows = $input.all();
const config = {};
for (const row of rows) {
  const k = row.json.key;
  const v = row.json.value;
  if (k) config[k] = String(v || '');
}
return [{ json: config }];

const wh = $('Baileys Webhook').first().json.body;
const rawJid = wh.from || '';
const phone = rawJid.split('@')[0];

const allowed = $('Config').first().json.ALLOWED_NUMBERS || '';
if (allowed.trim()) {
  const list = allowed.split(',').map(n => n.trim());
  if (!list.includes(phone)) {
    return [];
  }
}

return [{
  json: {
    phone: phone,
    jid: rawJid,
    profileName: wh.fromName || '',
    messageBody: wh.message || '',
    quotedText: wh.quotedText || '',
    timestamp: wh.timestamp || new Date().toISOString(),
    sessionDate: new Date().toISOString().slice(0, 10),
    hasVoice: wh.hasAudio === true,
    mediaUrl: wh.audioUrl || ''
  }
}];

const pw = $('Parse Webhook').first().json;
const transcription = $json?.text;
let messageBody = transcription || pw.messageBody;

if (!messageBody || !messageBody.trim()) {
  return [];
}

if (pw.quotedText && pw.quotedText.trim()) {
  messageBody = '[Replying to: "' + pw.quotedText.trim() + '"] ' + messageBody;
}

return [{
  json: {
    phone: pw.phone,
    jid: pw.jid,
    profileName: pw.profileName,
    messageBody: messageBody,
    timestamp: pw.timestamp,
    sessionDate: pw.sessionDate
  }
}];

const agentOutput = $input.first().json;
const raw = agentOutput.output || agentOutput.text || '';

let orderData = null;
let handoffData = null;
let aiReply = raw;

const orderMatch = raw.match(/<<<ORDER:(.*?)>>>/s);
if (orderMatch) {
  try { orderData = JSON.parse(orderMatch[1]); } catch (e) {}
  aiReply = raw.replace(/<<<ORDER:.*?>>>/s, '').trim();
}

const handoffMatch = raw.match(/<<<HANDOFF:(.*?)>>>/s);
if (handoffMatch) {
  try { handoffData = JSON.parse(handoffMatch[1]); } catch (e) {}
  aiReply = raw.replace(/<<<HANDOFF:.*?>>>/s, '').trim();
}

let action = 'chat';
if (orderData) action = 'order';
else if (handoffData) action = 'handoff';

return [{ json: { aiReply, orderData, handoffData, action } }];

const botConfig = $('Bot Config Map').first().json;
const wasVoice = $('Parse Webhook').first().json.hasVoice;

let agentOutput = null;
try {
  agentOutput = $('AI Agent').first().json;
} catch (e) {
  agentOutput = null;
}

let estInputTokens, estOutputTokens, claudeCost;

if (agentOutput) {
  const outputText = agentOutput.output || '';
  const steps = agentOutput.steps || [];
  const hadToolUse = steps.length > 0;

  estInputTokens = hadToolUse ? 2500 : 1000;
  estOutputTokens = Math.ceil(outputText.length / 4);
  claudeCost = (estInputTokens * 0.25 + estOutputTokens * 1.25) / 1000000;
} else {
  estInputTokens = 400;
  estOutputTokens = 15;
  claudeCost = (estInputTokens * 0.25 + estOutputTokens * 1.25) / 1000000;
}

const currentClaudeSpent = parseFloat(botConfig.CLAUDE_SPENT || '0');
const newClaudeSpent = (currentClaudeSpent + claudeCost).toFixed(6);

const items = [{ json: { key: 'CLAUDE_SPENT', value: newClaudeSpent } }];

if (wasVoice) {
  const currentWhisperSpent = parseFloat(botConfig.WHISPER_SPENT || '0');
  const whisperCost = 0.006;
  const newWhisperSpent = (currentWhisperSpent + whisperCost).toFixed(6);
  items.push({ json: { key: 'WHISPER_SPENT', value: newWhisperSpent } });
}

return items;

const vars = $('Extract Message').first().json;
return [{
  json: {
    userMessage: vars.messageBody,
    phone: vars.phone,
    turnNote: ''
  }
}];

const phone = $('Extract Message').first().json.phone;
const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
rows.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
const row = rows[0];

if (!row) {
  return [{ json: { awaiting: false, phone } }];
}

const minutesSince = (Date.now() - new Date(row.timestamp).getTime()) / 60000;
if (!(minutesSince <= 30)) {
  return [{ json: { awaiting: false, expired: true, phone, _id: String(row._id), awaitingConfirmation: false } }];
}

return [{
  json: {
    awaiting: true,
    pendingOrderPayload: row.pendingOrderPayload || {},
    reason: row.reason || '',
    phone: row.phone,
    _id: String(row._id),
    customerMessage: $('Extract Message').first().json.messageBody
  }
}];

const allItems = $input.all();
const pending = $('Compute Pending Status').first().json;
const maxCtx = parseInt(($('Bot Config Map').first().json.MAX_CONTEXT_MESSAGES || '20'), 10);

let historyLines = [];
// Mongo returns newest first -> reverse to chronological order
for (const item of allItems.slice().reverse()) {
  const row = item.json;
  if (!row.message || !row.role) continue;
  const who = row.role === 'assistant' ? 'Bot' : 'Customer';
  historyLines.push(who + ': ' + String(row.message));
}
historyLines = historyLines.slice(-(maxCtx - 1));
const conversationHistory = historyLines.length > 0 ? historyLines.join('\n') : '(no recent history)';

return [{
  json: {
    phone: pending.phone,
    pendingOrderPayload: pending.pendingOrderPayload,
    reason: pending.reason,
    customerMessage: pending.customerMessage,
    _id: pending._id,
    conversationHistory
  }
}];

const item = $input.first().json;
const raw = item.text || (item.response && item.response.text) || item.output || '';
let rawResult = 'unclear';
try {
  const match = String(raw).match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(match ? match[0] : raw);
  if (['confirmed', 'declined', 'modify', 'unclear'].includes(parsed.result)) {
    rawResult = parsed.result;
  }
} catch (e) {
  rawResult = 'unclear';
}

// modify and declined route identically downstream -- both clear the pending flag
// and hand off to a fresh, independent conversation. Keep the real classification
// visible separately for debugging.
const result = (rawResult === 'modify') ? 'declined' : rawResult;

const pending = $('Compute Pending Status').first().json;
return [{
  json: {
    result,
    classifiedAs: rawResult,
    phone: pending.phone,
    _id: pending._id,
    awaitingConfirmation: false,
    pendingOrderPayload: pending.pendingOrderPayload
  }
}];

const parsed = $('Parse Confirmation').first().json;
const pending = parsed.pendingOrderPayload || {};
const items = pending.items || [];
const total = pending.total || 0;
const itemLines = items.map(i => '- ' + i.name + ' x' + i.qty).join('\n');
const msg = 'Aap ka order confirm ho gaya:\n' + itemLines + '\nTotal: Rs. ' + total + '\nRider ke pass jaate hi aapko alert mil jayega.';
const orderTag = '<<<ORDER:' + JSON.stringify(pending) + '>>>';
return [{ json: { output: msg + '\n' + orderTag } }];

const classifyInput = $('Build Classify Input').first().json;
const vars = $('Extract Message').first().json;

const pendingNote = 'You previously asked the customer to confirm whether to proceed with this pending order: ' +
  JSON.stringify(classifyInput.pendingOrderPayload) +
  '. Their last reply did not clearly say yes or no to that question. First briefly address ' +
  'whatever they just said, then politely ask again for confirmation as a numbered list: ' +
  '1. Confirm  2. Cancel  3. Modify. Do not append the ORDER tag until they clearly confirm ' +
  'this specific pending order.';

return [{
  json: {
    userMessage: vars.messageBody,
    phone: vars.phone,
    turnNote: pendingNote
  }
}];

const phone = $('Extract Message').first().json.phone;
const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
rows.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
const row = rows[0];

if (!row) {
  return [{ json: { awaiting: false, phone } }];
}

const minutesSince = (Date.now() - new Date(row.timestamp).getTime()) / 60000;
if (!(minutesSince <= 30)) {
  return [{ json: { awaiting: false, expired: true, phone, _id: String(row._id), awaitingConfirmation: false } }];
}

return [{
  json: {
    awaiting: true,
    orderId: row.orderId,
    items: Array.isArray(row.items) ? row.items : [],
    total: row.total,
    address: row.address,
    status: row.status,
    orderTimestamp: row.timestamp,
    phone: row.phone,
    _id: String(row._id),
    customerMessage: $('Extract Message').first().json.messageBody
  }
}];

const allItems = $input.all();
const pending = $('Compute Pending Cancellation Status').first().json;
const maxCtx = parseInt(($('Bot Config Map').first().json.MAX_CONTEXT_MESSAGES || '20'), 10);

let historyLines = [];
// Mongo returns newest first -> reverse to chronological order
for (const item of allItems.slice().reverse()) {
  const row = item.json;
  if (!row.message || !row.role) continue;
  const who = row.role === 'assistant' ? 'Bot' : 'Customer';
  historyLines.push(who + ': ' + String(row.message));
}
historyLines = historyLines.slice(-(maxCtx - 1));
const conversationHistory = historyLines.length > 0 ? historyLines.join('\n') : '(no recent history)';

return [{
  json: {
    phone: pending.phone,
    orderId: pending.orderId,
    items: pending.items,
    total: pending.total,
    address: pending.address,
    status: pending.status,
    orderTimestamp: pending.orderTimestamp,
    customerMessage: pending.customerMessage,
    _id: pending._id,
    conversationHistory
  }
}];

const item = $input.first().json;
const raw = item.text || (item.response && item.response.text) || item.output || '';
let result = 'unclear';
try {
  const match = String(raw).match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(match ? match[0] : raw);
  if (['confirmed', 'declined', 'unclear'].includes(parsed.result)) {
    result = parsed.result;
  }
} catch (e) {
  result = 'unclear';
}

const pending = $('Build Cancellation Classify Input').first().json;
return [{
  json: {
    result,
    phone: pending.phone,
    _id: pending._id,
    awaitingConfirmation: false,
    orderId: pending.orderId,
    items: pending.items,
    total: pending.total,
    address: pending.address,
    status: pending.status,
    orderTimestamp: pending.orderTimestamp
  }
}];

const parsed = $('Parse Cancellation Confirmation').first().json;
const items = parsed.items || [];
const itemLines = items.map(i => '- ' + i.name + ' x' + i.qty).join('; ');
const msg = 'Theek hai, aap ki request team ko bhej di gayi hai. Order ID ' + parsed.orderId + ' ke baare mein team aap se rabta karegi.';
const handoffReason = 'Customer confirmed cancel/modify request for placed order ' + parsed.orderId +
  ' (items: ' + itemLines + ', total: Rs. ' + parsed.total +
  ', address: ' + parsed.address + ', status at request time: ' + parsed.status +
  ', order placed at: ' + parsed.orderTimestamp + ')';
const handoffTag = '<<<HANDOFF:' + JSON.stringify({ reason: handoffReason }) + '>>>';
return [{ json: { output: msg + '\n' + handoffTag } }];

const classifyInput = $('Build Cancellation Classify Input').first().json;
const vars = $('Extract Message').first().json;

const pendingNote = 'You previously asked the customer to confirm whether to cancel/modify this already-placed order: ' +
  'Order ID ' + classifyInput.orderId + ', items ' + JSON.stringify(classifyInput.items) +
  ', total Rs. ' + classifyInput.total + ', status ' + classifyInput.status +
  '. Their last reply did not clearly confirm or decline that. First briefly address ' +
  'whatever they just said, then politely ask again for confirmation as a numbered list: ' +
  '1. Confirm cancel/modify  2. Keep the order as is. Do not append the HANDOFF tag yourself -- ' +
  'this is handled automatically once they clearly confirm.';

return [{
  json: {
    userMessage: vars.messageBody,
    phone: vars.phone,
    turnNote: pendingNote
  }
}];

const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
if (rows.length === 0) {
  return [{ json: { status: '' } }];
}

rows.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
const latest = rows[0];

return [{
  json: {
    status: latest.status || '',
    reason: latest.reason || '',
    _id: String(latest._id),
    timestamp: latest.timestamp
  }
}];

// Data sources:
//   $('Extract Message').first().json -> phone, profileName, messageBody, timestamp, sessionDate
//   $('Process Reply').first().json   -> aiReply
// Output: 2 items (user message, assistant reply) shaped like the Conversation collection.
const m = $('Extract Message').first().json;
const reply = $('Process Reply').first().json;

function toIso(ts) {
  if (typeof ts === 'number' || /^\d+$/.test(String(ts || ''))) {
    const n = Number(ts);
    const d = new Date(n < 1e12 ? n * 1000 : n);
    if (!isNaN(d)) return d.toISOString();
  }
  const d = new Date(ts);
  return isNaN(d) ? new Date().toISOString() : d.toISOString();
}

return [
  { json: {
      phone: m.phone,
      profileName: m.profileName,
      message: m.messageBody,
      role: 'user',
      timestamp: toIso(m.timestamp),
      sessionId: m.sessionDate
  } },
  { json: {
      phone: m.phone,
      profileName: 'BOT',
      message: reply.aiReply,
      role: 'assistant',
      timestamp: new Date().toISOString(),
      sessionId: m.sessionDate
  } }
];

function normalizeItems(raw) {
  let arr = raw;
  if (typeof arr === 'string') { try { arr = JSON.parse(arr); } catch (e) { arr = []; } }
  if (!Array.isArray(arr)) arr = [];
  return arr.filter(i => i && i.name).map(i => {
    const out = { name: String(i.name), qty: Number(i.qty || 1) };
    const price = Number(i.price);
    if (i.price !== undefined && i.price !== null && i.price !== '' && isFinite(price)) out.price = price;
    return out;
  });
}

// Data sources:
//   $('Extract Message').first().json -> phone, profileName, jid
//   $('Process Reply').first().json.orderData -> items, total, address (from the <<<ORDER:...>>> tag)
const m = $('Extract Message').first().json;
const od = $('Process Reply').first().json.orderData || {};
const total = Number(od.total);

return [{ json: {
  orderId: 'OTTO-' + Date.now(),
  timestamp: new Date().toISOString(),
  phone: m.phone,
  profileName: m.profileName,
  items: normalizeItems(od.items),
  totalAmount: isFinite(total) ? total : 0,
  deliveryAddress: od.address || '',
  status: 'preparing',
  notes: '',
  jid: m.jid
} }];

// Data sources:
//   $('Extract Message').first().json -> phone, profileName, messageBody
//   $('Process Reply').first().json.handoffData -> reason (from the <<<HANDOFF:...>>> tag)
const m = $('Extract Message').first().json;
const h = $('Process Reply').first().json.handoffData || {};

return [{ json: {
  timestamp: new Date().toISOString(),
  phone: m.phone,
  profileName: m.profileName,
  reason: h.reason || '',
  lastMessage: m.messageBody,
  status: 'active'
} }];
